import java.util.*;

class Solution {
  public int maximumPoints(int[][] edges, int[] coins, int k) {
    int n = coins.length;
    List<Integer>[] g = new ArrayList[n];
    for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
    for (int[] e : edges) {
      g[e[0]].add(e[1]);
      g[e[1]].add(e[0]);
    }
    int[] par = new int[n];
    Arrays.fill(par, -2);
    int[] ord = new int[n];
    int z = 0;
    ord[z++] = 0;
    par[0] = -1;
    for (int i = 0; i < z; i++)
      for (int v : g[ord[i]])
        if (par[v] == -2) {
          par[v] = ord[i];
          ord[z++] = v;
        }
    long[][] dp = new long[n][15];
    for (int ii = n - 1; ii >= 0; ii--) {
      int u = ord[ii];
      for (int t = 14; t >= 0; t--) {
        long a = Math.max(0, coins[u] >> t) - k, b = (coins[u] >> t) / 2;
        for (int v : g[u])
          if (v != par[u]) {
            a += dp[v][t];
            b += dp[v][Math.min(14, t + 1)];
          }
        dp[u][t] = Math.max(a, b);
      }
    }
    return (int) dp[0][0];
  }
}
